@Async("customizeThreadPool")
@Scheduled(initialDelay = 10000, fixedDelayString = "${hicoo.task.scan.delay:60000}")
public void hicooDataSync(){
    if (!taskScanEnable){
        LOGGER.info("hicoo数据同步任务扫描未开启");
        return;
    }

    LOGGER.info("hicoo数据同步任务扫描开始");

    //查询所有未完成的任务
    LambdaQueryWrapper<ConfHicooTaskTab> ql = new LambdaQueryWrapper<ConfHicooTaskTab>().eq(ConfHicooTaskTab::getTaskStatus, 0);
    List<ConfHicooTaskTab> lstTab = confHicooTaskService.list(ql);

    if (lstTab != null && lstTab.size() > 0) {
        List<ConfHicooTaskTab> lstProductModel = new ArrayList<>();
        List<ConfHicooTaskTab> lstSalesId = new ArrayList<>();
        List<String> lstTaskId = new ArrayList<>();
        List<String> lstProductModelAll = new ArrayList<>();
        List<String> lstSalesIdAll = new ArrayList<>();
        List<String> lstSpsTask = new ArrayList<>();

        for (ConfHicooTaskTab confHicooTaskTab : lstTab) {
            if (confHicooTaskTab.getTaskType() == 1) {
                //同步所有数据
                lstTaskId.add(confHicooTaskTab.getTaskId());
            } else if (confHicooTaskTab.getTaskType() == 11) {
                //同步产品指定数据
                String productModel = confHicooTaskTab.getProductModel().trim();
                if (StringUtils.hasLength(productModel)){
                    if (lstProductModel.contains(productModel)){
                        continue;
                    }
                    lstProductModel.add(confHicooTaskTab);
                }
            } else if (confHicooTaskTab.getTaskType() == 21) {
                //同步算法销售项指定数据
                String salesId = confHicooTaskTab.getSalesId().trim();
                if (StringUtils.hasLength(salesId)){
                    if (lstSalesId.contains(salesId)){
                        continue;
                    }
                    lstSalesId.add(confHicooTaskTab);
                }
            } else if (confHicooTaskTab.getTaskType() == 111) {
                lstProductModelAll.add(confHicooTaskTab.getTaskId());
            } else if (confHicooTaskTab.getTaskType() == 211) {
                lstSalesIdAll.add(confHicooTaskTab.getTaskId());
            } else if (confHicooTaskTab.getTaskType() == 31) {
                //同步sps数据
                lstSpsTask.add(confHicooTaskTab.getTaskId());
            }

        }

        if (lstTaskId.size() > 0){
            hicooServcieBiz.taskAllUpdate(1, lstTaskId);
        } else {
            if (lstProductModel.size() > 0) {
                hicooServcieBiz.taskProductUpdate(lstProductModel);
            }

            if (lstSalesId.size() > 0) {
                hicooServcieBiz.taskSaleUpdate(lstSalesId);
            }

            if (lstProductModelAll.size() > 0) {
                hicooServcieBiz.taskAllUpdate(111, lstProductModelAll);
            }

            if (lstSalesIdAll.size() > 0) {
                hicooServcieBiz.taskAllUpdate(211, lstSalesIdAll);
            }

            if (lstSpsTask.size() > 0) {
                confServerListServiceBiz.saveConfServerList();
            }
        }
    }

}

/**
 * 候选自身状态异常时，沿其 replace_models 链递归向上查找直到状态正常
 *
 * @param badRow 状态异常的候选
 * @param depth 当前递归深度
 * @return 沿链找到的状态正常替代服务器，找不到返回 null
 */
private ConfServerListTab followChain(ConfServerListTab badRow, int depth) {
    if (depth >= MAX_REPLACE_DEPTH) {
        return null;
    }
    String badRowReplaceModels = badRow.getReplaceModels();
    if (StringUtils.isBlank(badRowReplaceModels)) {
        return null;
    }
    return findReplaceServer(badRowReplaceModels, depth + 1);
}
